--
-- Name: cancel_payroll_run(bigint, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cancel_payroll_run(p_run_id bigint, p_user text, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$

declare

    v_run          payroll_runs%rowtype;

    v_blocked      integer;

begin

    select * into v_run

    from payroll_runs

    where id = p_run_id

    for update;



    if not found then

        raise exception 'Payroll run % not found', p_run_id;

    end if;



    if v_run.status = 'cancelled' then

        raise exception 'Payroll run % is already cancelled', p_run_id;

    end if;



    -- If it was posted, we need to remove the ledger rows first.

    if v_run.status = 'posted' then

        -- Refuse if any linked transaction has moved past 'draft'

        select count(*) into v_blocked

        from transactions

        where payroll_run_id = p_run_id

          and status not in ('draft', 'posted');



        if v_blocked > 0 then

            raise exception 'Cannot cancel: % linked transaction(s) are already approved or rejected. Reverse them manually first.', v_blocked;

        end if;



        delete from transactions

        where payroll_run_id = p_run_id;

    end if;



    update payroll_runs

    set status       = 'cancelled',

        cancelled_at = now(),

        cancelled_by = p_user,

        cancel_reason = coalesce(p_reason, 'No reason provided')

    where id = p_run_id;



    insert into audit_logs (

        id,

        timestamp,

        user_name,

        action,

        target,

        details,

        old_value,

        new_value,

        warning

    ) values (

        'audit_' || extract(epoch from clock_timestamp())::bigint || '_' || floor(random() * 100000)::text,

        now(),

        p_user,

        'CANCEL',

        'Payroll #' || p_run_id,

        'Cancelled payroll for ' || v_run.period || ' (was ' || v_run.status || '). Reason: ' || coalesce(p_reason, 'not provided'),

        v_run.status,

        'cancelled',

        false

    );

end;

$$;


ALTER FUNCTION public.cancel_payroll_run(p_run_id bigint, p_user text, p_reason text) OWNER TO postgres;

--
-- Name: detect_duplicate_transaction(text, numeric, date, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.detect_duplicate_transaction(p_reference text, p_amount numeric, p_actual_date date, p_type text, p_exclude_id text DEFAULT NULL::text) RETURNS TABLE(existing_id text, existing_reference text, existing_amount numeric, existing_date date, existing_type text)
    LANGUAGE plpgsql STABLE
    AS $$

BEGIN

  IF p_reference IS NULL OR trim(p_reference) = '' THEN

    RETURN;

  END IF;



  RETURN QUERY

  SELECT t.id,

         t.reference,

         t.amount,

         COALESCE(t.actual_date, t.date),

         t.type

  FROM transactions t

  WHERE t.deleted_at IS NULL

    AND t.reversed_at IS NULL

    AND upper(trim(t.reference)) = upper(trim(p_reference))

    AND (p_exclude_id IS NULL OR t.id <> p_exclude_id);

END;

$$;


ALTER FUNCTION public.detect_duplicate_transaction(p_reference text, p_amount numeric, p_actual_date date, p_type text, p_exclude_id text) OWNER TO postgres;

--
-- Name: equity_as_of(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.equity_as_of(p_as_of date DEFAULT CURRENT_DATE) RETURNS TABLE(investor_id bigint, name text, investor_number text, equity numeric, pct numeric, last_change text, last_ref text, last_date date, is_current boolean)
    LANGUAGE plpgsql STABLE
    AS $$

BEGIN

  RETURN QUERY

  WITH last_txn AS (

    SELECT DISTINCT ON (st.investor_id)

      st.investor_id,

      st.action,

      st.reference,

      st.date,

      st.equity_after

    FROM share_transactions st

    WHERE st.date <= p_as_of

    ORDER BY st.investor_id, st.date DESC, st.id DESC

  ),

  holders AS (

    SELECT

      i.id           AS investor_id,

      i.name         AS name,

      i.investor_number AS investor_number,

      COALESCE(lt.equity_after, 0) AS equity,

      lt.action      AS last_change,

      lt.reference   AS last_ref,

      lt.date        AS last_date,

      (i.deleted_at IS NULL) AS is_current

    FROM investors i

    LEFT JOIN last_txn lt ON lt.investor_id = i.id

    WHERE

      (i.joined_date IS NOT NULL AND i.joined_date <= p_as_of)

      OR

      (lt.investor_id IS NOT NULL)

      OR

      (i.deleted_at IS NULL AND i.joined_date IS NULL)

  )

  SELECT

    h.investor_id,

    h.name,

    h.investor_number,

    COALESCE(h.equity, 0) AS equity,

    CASE

      WHEN SUM(h.equity) OVER () > 0

      THEN ROUND((COALESCE(h.equity, 0) / SUM(h.equity) OVER ()) * 100, 4)

      ELSE 0

    END AS pct,

    h.last_change,

    h.last_ref,

    h.last_date,

    h.is_current

  FROM holders h

  WHERE COALESCE(h.equity, 0) > 0

  ORDER BY COALESCE(h.equity, 0) DESC;

END;

$$;


ALTER FUNCTION public.equity_as_of(p_as_of date) OWNER TO postgres;

--
-- Name: is_valid_task_transition(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.is_valid_task_transition(p_from text, p_to text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    AS $$

declare

  valid_from text[] := array['draft','assigned','accepted','in_progress','awaiting_review','approved','rejected','completed','on_hold','cancelled'];

  allowed jsonb := '{

    "draft": ["assigned","cancelled"],

    "assigned": ["accepted","rejected"],

    "accepted": ["in_progress","on_hold"],

    "in_progress": ["awaiting_review","on_hold"],

    "awaiting_review": ["approved","rejected"],

    "approved": ["completed"],

    "rejected": ["in_progress","cancelled"],

    "on_hold": ["in_progress"],

    "completed": ["in_progress"]

  }'::jsonb;

begin

  if not (p_from = any(valid_from)) then return false; end if;

  return allowed->p_from ? p_to;

end;

$$;


ALTER FUNCTION public.is_valid_task_transition(p_from text, p_to text) OWNER TO postgres;

--
-- Name: mark_dividend_paid(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.mark_dividend_paid(p_dividend_id text, p_actor text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$

DECLARE

  v_div          record;

  v_alloc        jsonb;

  v_alloc_count  int := 0;

  v_txn_ids      text[] := ARRAY[]::text[];

  v_txn_id       text;

  v_investor_id  bigint;

  v_investor_ref text;

  v_amount       numeric;

  v_name         text;

  v_pay_date     date;

BEGIN

  -- 1. Load the dividend

  SELECT id, period_label, status, total_distributable, allocations,

         COALESCE(paid_at, now())::date AS paid_date

  INTO v_div

  FROM dividends

  WHERE id = p_dividend_id

  FOR UPDATE;



  IF NOT FOUND THEN

    RAISE EXCEPTION 'Dividend % not found', p_dividend_id;

  END IF;



  IF v_div.status NOT IN ('approved', 'paid') THEN

    RAISE EXCEPTION 'Dividend must be approved before it can be paid (current status: %)', v_div.status;

  END IF;



  -- Idempotency: if linked_txn_ids already exists on the dividend, skip re-creation.

  IF (SELECT linked_txn_ids FROM dividends WHERE id = p_dividend_id) IS NOT NULL THEN

    RETURN jsonb_build_object(

      'status', 'already_paid',

      'message', 'This dividend already has linked transactions'

    );

  END IF;



  v_pay_date := v_div.paid_date;



  -- 2. Iterate allocations

  IF v_div.allocations IS NULL OR jsonb_array_length(v_div.allocations) = 0 THEN

    RAISE EXCEPTION 'Dividend has no allocations';

  END IF;



  FOR v_alloc IN SELECT * FROM jsonb_array_elements(v_div.allocations)

  LOOP

    v_amount := COALESCE((v_alloc->>'amount')::numeric, 0);

    v_name   := COALESCE(v_alloc->>'name', 'Unknown');



    IF v_amount <= 0 THEN

      CONTINUE;  -- skip zero-amount allocations

    END IF;



    -- Resolve investor id: numeric InvestorId is a real FK,

    -- 'virtual_*' strings mean the STARLINK VIRTUAL pseudo-investor

    v_investor_ref := COALESCE(v_alloc->>'InvestorId', '');

    IF v_investor_ref ~ '^[0-9]+$' THEN

      v_investor_id := v_investor_ref::bigint;

    ELSE

      v_investor_id := NULL;  -- virtual investor, no FK

    END IF;



    -- Generate a stable transaction id

    v_txn_id := 'TXN-DIV-' || p_dividend_id || '-' || COALESCE(v_investor_ref, 'x');



    -- Insert the transaction (idempotent via idempotency_key)

    INSERT INTO transactions (

      id, date, actual_date, type, category, description,

      amount, fee, method, reference, status, source,

      idempotency_key, notes, created_by, created_at

    ) VALUES (

      v_txn_id,

      v_pay_date,

      v_pay_date,

      'expense',

      'Dividend Payment',

      'Dividend ' || v_div.period_label || ' — ' || v_name,

      v_amount,

      0,

      'bank',

      'DIV-' || p_dividend_id || '-' || COALESCE(v_investor_ref, 'x'),

      'posted',

      'dividend',

      'dividend-' || p_dividend_id || '-' || COALESCE(v_investor_ref, 'x'),

      'Auto-created when dividend marked paid. Virtual investor allocation included.' ,

      p_actor,

      now()

    )

    ON CONFLICT (id) DO NOTHING;



    v_txn_ids := array_append(v_txn_ids, v_txn_id);

    v_alloc_count := v_alloc_count + 1;

  END LOOP;



  -- 3. Update the dividend

  UPDATE dividends

  SET status         = 'paid',

      paid_at        = COALESCE(paid_at, now()),

      linked_txn_ids = v_txn_ids,

      updated_at     = now(),

      updated_by     = p_actor

  WHERE id = p_dividend_id;



  RETURN jsonb_build_object(

    'status',           'paid',

    'dividend_id',      p_dividend_id,

    'transactions_created', v_alloc_count,

    'txn_ids',          v_txn_ids

  );

END;

$_$;


ALTER FUNCTION public.mark_dividend_paid(p_dividend_id text, p_actor text) OWNER TO postgres;

--
-- Name: next_task_id(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.next_task_id() RETURNS text
    LANGUAGE plpgsql
    AS $_$

declare

  max_n int;

begin

  select coalesce(max(cast(regexp_replace(id, '^TSK-', '') as int)), 0) into max_n

  from tasks where id ~ '^TSK-[0-9]+$';

  return 'TSK-' || lpad((max_n + 1)::text, 5, '0');

end;

$_$;


ALTER FUNCTION public.next_task_id() OWNER TO postgres;

--
-- Name: post_payroll_run(bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.post_payroll_run(p_run_id bigint, p_user text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$

declare

    v_run              payroll_runs%rowtype;

    v_item             payroll_items%rowtype;

    v_txn_id           text;

    v_seq              integer;

    v_year             text;

    v_total_net        numeric(14,2) := 0;

    v_item_count       integer := 0;

    v_staff_name       text;

begin

    select * into v_run

    from payroll_runs

    where id = p_run_id

    for update;



    if not found then

        raise exception 'Payroll run % not found', p_run_id;

    end if;



    if v_run.status <> 'approved' then

        raise exception 'Payroll run must be in "approved" state to post (currently: %)', v_run.status;

    end if;



    v_year := to_char(coalesce(v_run.run_date, current_date), 'YYYY');



    select coalesce(max(

        case

            when t.id ~ ('^TXN-' || v_year || '-[0-9]{6}$')

            then substring(t.id from 10 for 6)::integer

            else 0

        end

    ), 0)

    into v_seq

    from transactions t;



    for v_item in

        select * from payroll_items

        where run_id = p_run_id

        order by id

    loop

        v_seq := v_seq + 1;

        v_txn_id := 'TXN-' || v_year || '-' || lpad(v_seq::text, 6, '0');



        select full_name into v_staff_name

        from staff

        where id = v_item.staff_id;



        insert into transactions (

            id,

            date,

            type,

            category,

            description,

            amount,

            method,

            reference,

            location,

            location_id,

            status,

            recon_status,

            notes,

            staff_id,

            payroll_run_id,

            created_at,

            created_by,

            approved_at,

            approved_by

        ) values (

            v_txn_id,

            coalesce(v_run.run_date, current_date),

            'expense',

            'Salaries',

            'Payroll ' || v_run.period || ' — ' || coalesce(v_staff_name, 'Staff #' || v_item.staff_id),

            v_item.net,

            'bank',

            'PAYROLL-' || v_run.period,

            null,

            (select location_id from staff where id = v_item.staff_id),

            'posted',

            'na',

            coalesce(v_item.notes, 'Payroll item for period ' || v_run.period),

            v_item.staff_id,

            p_run_id,

            now(),

            p_user,

            now(),

            p_user

        );



        update payroll_items

        set transaction_id = v_txn_id

        where id = v_item.id;



        v_total_net := v_total_net + coalesce(v_item.net, 0);

        v_item_count := v_item_count + 1;

    end loop;



    if v_item_count = 0 then

        raise exception 'Payroll run % has no items to post', p_run_id;

    end if;



    update payroll_runs

    set status       = 'posted',

        posted_at    = now(),

        posted_by    = p_user,

        total_gross  = v_total_net,

        total_net    = v_total_net,

        total_deductions = 0

    where id = p_run_id;



    insert into audit_logs (

        id,

        timestamp,

        user_name,

        action,

        target,

        details,

        old_value,

        new_value,

        warning

    ) values (

        'audit_' || extract(epoch from clock_timestamp())::bigint || '_' || floor(random() * 100000)::text,

        now(),

        p_user,

        'PAID',

        'Payroll #' || p_run_id,

        'Posted payroll for ' || v_run.period || ' — '

            || v_item_count::text || ' staff — KSh ' || v_total_net::text,

        v_run.status,

        'posted',

        false

    );

end;

$_$;


ALTER FUNCTION public.post_payroll_run(p_run_id bigint, p_user text) OWNER TO postgres;

--
-- Name: post_transaction(text, date, date, time without time zone, text, text, text, numeric, numeric, text, text, text, bigint, bigint, bigint, text, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.post_transaction(p_id text, p_date date, p_actual_date date, p_actual_time time without time zone, p_type text, p_category text, p_description text, p_amount numeric, p_fee numeric, p_method text, p_reference text, p_location text, p_location_id bigint, p_staff_id bigint, p_payroll_run_id bigint, p_notes text, p_source text, p_idempotency_key text, p_created_by text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$

DECLARE

  v_existing_id text;

  v_dup_count   int;

BEGIN

  -- 1. Idempotency check

  IF p_idempotency_key IS NOT NULL THEN

    SELECT id INTO v_existing_id

    FROM transactions

    WHERE idempotency_key = p_idempotency_key

    LIMIT 1;



    IF v_existing_id IS NOT NULL THEN

      RETURN v_existing_id;  -- already posted — return existing

    END IF;

  END IF;



  -- 2. Duplicate check

  SELECT COUNT(*) INTO v_dup_count

  FROM detect_duplicate_transaction(

    p_reference, p_amount, p_actual_date, p_type, NULL

  );



  IF v_dup_count > 0 THEN

    RAISE EXCEPTION 'Duplicate transaction detected for reference %', p_reference

      USING ERRCODE = '23505';

  END IF;



  -- 3. Insert

  INSERT INTO transactions (

    id, date, actual_date, actual_time,

    type, category, description, amount, fee,

    method, reference, location, location_id, staff_id, payroll_run_id,

    status, notes, source, idempotency_key, created_by, created_at

  ) VALUES (

    p_id, p_date, COALESCE(p_actual_date, p_date), p_actual_time,

    p_type, p_category, p_description, p_amount, COALESCE(p_fee, 0),

    p_method, p_reference, p_location, p_location_id, p_staff_id, p_payroll_run_id,

    'draft', p_notes, COALESCE(p_source, 'manual'), p_idempotency_key,

    p_created_by, now()

  );



  RETURN p_id;

END;

$$;


ALTER FUNCTION public.post_transaction(p_id text, p_date date, p_actual_date date, p_actual_time time without time zone, p_type text, p_category text, p_description text, p_amount numeric, p_fee numeric, p_method text, p_reference text, p_location text, p_location_id bigint, p_staff_id bigint, p_payroll_run_id bigint, p_notes text, p_source text, p_idempotency_key text, p_created_by text) OWNER TO postgres;

--
-- Name: record_capital_injection(bigint, numeric, date, text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_capital_injection(p_investor_id bigint, p_amount numeric, p_date date, p_type text, p_reference text, p_notes text, p_reason text, p_actor text, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$

DECLARE

  v_investor          record;

  v_old_equity        numeric;

  v_new_equity        numeric;

  v_delta             numeric;

  v_total_before      numeric;

  v_total_after       numeric;

  v_pct_before        numeric;

  v_pct_after         numeric;

  v_investment_id     bigint;

  v_share_txn_id      bigint;

  v_action            text;

BEGIN

  -- 1. Idempotency check

  IF p_idempotency_key IS NOT NULL THEN

    SELECT id, investor_id, amount INTO v_investment_id, v_share_txn_id, v_delta

    FROM investments

    WHERE reference = p_idempotency_key

    LIMIT 1;



    IF v_investment_id IS NOT NULL THEN

      RETURN jsonb_build_object(

        'status', 'already_recorded',

        'investment_id', v_investment_id,

        'message', 'This injection was already recorded'

      );

    END IF;

  END IF;



  -- 2. Validate input

  IF p_amount IS NULL OR p_amount <= 0 THEN

    RAISE EXCEPTION 'Amount must be greater than 0';

  END IF;



  IF p_type NOT IN ('initial', 'additional', 'withdrawal') THEN

    RAISE EXCEPTION 'Type must be initial, additional, or withdrawal';

  END IF;



  -- 3. Lock and read the investor row

  SELECT id, equity, deleted_at

  INTO v_investor

  FROM investors

  WHERE id = p_investor_id

  FOR UPDATE;



  IF NOT FOUND THEN

    RAISE EXCEPTION 'Investor % not found', p_investor_id;

  END IF;



  IF v_investor.deleted_at IS NOT NULL THEN

    RAISE EXCEPTION 'Cannot inject capital into an archived investor';

  END IF;



  v_old_equity := COALESCE(v_investor.equity, 0);



  -- 4. Compute new equity (withdrawals subtract, everything else adds)

  IF p_type = 'withdrawal' THEN

    v_new_equity := v_old_equity - p_amount;

    IF v_new_equity < 0 THEN

      RAISE EXCEPTION 'Withdrawal would reduce equity below 0 (current: %, requested: %)',

        v_old_equity, p_amount;

    END IF;

    v_delta := -p_amount;

    v_action := 'buyback';

  ELSE

    v_new_equity := v_old_equity + p_amount;

    v_delta := p_amount;

    v_action := CASE p_type WHEN 'initial' THEN 'initial' ELSE 'additional' END;

  END IF;



  -- 5. Compute ownership percentages (before and after)

  --    Denominator = all non-archived investors' equity, with this one adjusted.

  SELECT COALESCE(SUM(equity), 0) INTO v_total_before

  FROM investors

  WHERE deleted_at IS NULL;



  v_total_after := v_total_before + v_delta;



  v_pct_before := CASE WHEN v_total_before > 0

                       THEN ROUND((v_old_equity / v_total_before) * 100, 4)

                       ELSE 0 END;

  v_pct_after  := CASE WHEN v_total_after  > 0

                       THEN ROUND((v_new_equity / v_total_after) * 100, 4)

                       ELSE 0 END;



  -- 6. Insert into investments

  INSERT INTO investments (

    investor_id, date, amount, type, reference, notes,

    created_at, created_by

  ) VALUES (

    p_investor_id, p_date, p_amount, p_type,

    COALESCE(p_reference, p_idempotency_key),

    p_notes, now(), p_actor

  )

  RETURNING id INTO v_investment_id;



  -- 7. Insert into share_transactions

  INSERT INTO share_transactions (

    investor_id, date, action,

    equity_before, equity_after, delta,

    pct_before, pct_after,

    reference, notes, reason,

    created_at, created_by

  ) VALUES (

    p_investor_id, p_date, v_action,

    v_old_equity, v_new_equity, v_delta,

    v_pct_before, v_pct_after,

    COALESCE(p_reference, p_idempotency_key),

    p_notes, p_reason,

    now(), p_actor

  )

  RETURNING id INTO v_share_txn_id;



  -- 8. Update investors.equity

  UPDATE investors

  SET equity = v_new_equity,

      updated_at = now()

  WHERE id = p_investor_id;



  -- 9. Return summary

  RETURN jsonb_build_object(

    'status',          'created',

    'investment_id',   v_investment_id,

    'share_txn_id',    v_share_txn_id,

    'investor_id',     p_investor_id,

    'equity_before',   v_old_equity,

    'equity_after',    v_new_equity,

    'delta',           v_delta,

    'pct_before',      v_pct_before,

    'pct_after',       v_pct_after,

    'total_before',    v_total_before,

    'total_after',     v_total_after

  );

END;

$$;


ALTER FUNCTION public.record_capital_injection(p_investor_id bigint, p_amount numeric, p_date date, p_type text, p_reference text, p_notes text, p_reason text, p_actor text, p_idempotency_key text) OWNER TO postgres;

--
-- Name: restore_record(text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.restore_record(p_table text, p_id text, p_actor text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$

BEGIN

  EXECUTE format(

    'UPDATE %I SET deleted_at = NULL, deleted_by = NULL, delete_reason = NULL WHERE id::text = $1',

    p_table

  ) USING p_id;

END;

$_$;


ALTER FUNCTION public.restore_record(p_table text, p_id text, p_actor text) OWNER TO postgres;

--
-- Name: set_net_amount(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_net_amount() RETURNS trigger
    LANGUAGE plpgsql
    AS $$

BEGIN

  NEW.net_amount := COALESCE(NEW.amount, 0) - COALESCE(NEW.fee, 0);

  IF NEW.actual_date IS NULL THEN

    NEW.actual_date := NEW.date;

  END IF;

  RETURN NEW;

END;

$$;


ALTER FUNCTION public.set_net_amount() OWNER TO postgres;

--
-- Name: write_audit_entry(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.write_audit_entry() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$

DECLARE

  v_action    text;

  v_before    jsonb;

  v_after     jsonb;

  v_entity_id text;

  v_changed   text[];

BEGIN

  IF TG_OP = 'INSERT' THEN

    v_action := 'INSERT';

    v_before := NULL;

    v_after  := to_jsonb(NEW);

    v_entity_id := COALESCE(NEW.id::text, NULL);

  ELSIF TG_OP = 'UPDATE' THEN

    v_action := 'UPDATE';

    v_before := to_jsonb(OLD);

    v_after  := to_jsonb(NEW);

    v_entity_id := COALESCE(NEW.id::text, NULL);



    SELECT array_agg(key)

    INTO v_changed

    FROM jsonb_each(v_after) a

    WHERE a.value IS DISTINCT FROM (v_before -> a.key);

  ELSE

    v_action := 'DELETE';

    v_before := to_jsonb(OLD);

    v_after  := NULL;

    v_entity_id := COALESCE(OLD.id::text, NULL);

  END IF;



  INSERT INTO audit_log (

    actor, action, module, entity_id,

    record_before, record_after, changed_fields

  ) VALUES (

    COALESCE(current_setting('request.jwt.claim.sub', true), 'system'),

    v_action,

    TG_TABLE_NAME,

    v_entity_id,

    v_before,

    v_after,

    v_changed

  );



  RETURN COALESCE(NEW, OLD);

END;

$$;


ALTER FUNCTION public.write_audit_entry() OWNER TO postgres;

--
-- Name: apply_rls(jsonb, integer); Type: FUNCTION; Schema: realtime; Owner: supabase_realtime_admin
--

CREATE FUNCTION realtime.apply_rls(wal jsonb, max_record_bytes integer DEFAULT (1024 * 1024)) RETURNS SETOF realtime.wal_rls
    LANGUAGE plpgsql
    AS $$
declare
    -- Regclass of the table e.g. public.notes
    entity_ regclass = (quote_ident(wal ->> 'schema') || '.' || quote_ident(wal ->> 'table'))::regclass;

    -- I, U, D, T: insert, update ...
    action realtime.action = (
        case wal ->> 'action'
            when 'I' then 'INSERT'
            when 'U' then 'UPDATE'
            when 'D' then 'DELETE'
            else 'ERROR'
        end
    );

    -- Is row level security enabled for the table
    is_rls_enabled bool = relrowsecurity from pg_class where oid = entity_;

    subscriptions realtime.subscription[] = array_agg(subs)
        from
            realtime.subscription subs
        where
            subs.entity = entity_
            -- Filter by action early - only get subscriptions interested in this action
            -- action_filter column can be: '*' (all), 'INSERT', 'UPDATE', or 'DELETE'
            and (subs.action_filter = '*' or subs.action_filter = action::text);

    -- Subscription vars
    working_role regrole;
    working_selected_columns text[];
    claimed_role regrole;
    claims jsonb;

    subscription_id uuid;
    subscription_has_access bool;
    visible_to_subscription_ids uuid[] = '{}';

    -- structured info for wal's columns
    columns realtime.wal_column[];
    -- previous identity values for update/delete
    old_columns realtime.wal_column[];

    error_record_exceeds_max_size boolean = octet_length(wal::text) > max_record_bytes;

    -- Primary jsonb output for record
    output jsonb;

    -- Loop record for iterating unique roles (outer loop)
    role_record record;
    -- Loop record for iterating unique selected_columns within a role (inner loop)
    cols_record record;
    -- Subscription ids visible at the role level (before fanning out by selected_columns)
    visible_role_sub_ids uuid[] = '{}';

begin
    perform set_config('role', null, true);

    columns =
        array_agg(
            (
                x->>'name',
                x->>'type',
                x->>'typeoid',
                realtime.cast(
                    (x->'value') #>> '{}',
                    coalesce(
                        (x->>'typeoid')::regtype, -- null when wal2json version <= 2.4
                        (x->>'type')::regtype
                    )
                ),
                (pks ->> 'name') is not null,
                true
            )::realtime.wal_column
        )
        from
            jsonb_array_elements(wal -> 'columns') x
            left join jsonb_array_elements(wal -> 'pk') pks
                on (x ->> 'name') = (pks ->> 'name');

    old_columns =
        array_agg(
            (
                x->>'name',
                x->>'type',
                x->>'typeoid',
                realtime.cast(
                    (x->'value') #>> '{}',
                    coalesce(
                        (x->>'typeoid')::regtype, -- null when wal2json version <= 2.4
                        (x->>'type')::regtype
                    )
                ),
                (pks ->> 'name') is not null,
                true
            )::realtime.wal_column
        )
        from
            jsonb_array_elements(wal -> 'identity') x
            left join jsonb_array_elements(wal -> 'pk') pks
                on (x ->> 'name') = (pks ->> 'name');

    for role_record in
        select claims_role
        from (select distinct claims_role from unnest(subscriptions)) t
        order by claims_role::text
    loop
        working_role := role_record.claims_role;

        -- Update `is_selectable` for columns and old_columns (once per role)
        columns =
            array_agg(
                (
                    c.name,
                    c.type_name,
                    c.type_oid,
                    c.value,
                    c.is_pkey,
                    pg_catalog.has_column_privilege(working_role, entity_, c.name, 'SELECT')
                )::realtime.wal_column
            )
            from
                unnest(columns) c;

        old_columns =
                array_agg(
                    (
                        c.name,
                        c.type_name,
                        c.type_oid,
                        c.value,
                        c.is_pkey,
                        pg_catalog.has_column_privilege(working_role, entity_, c.name, 'SELECT')
                    )::realtime.wal_column
                )
                from
                    unnest(old_columns) c;

        if action <> 'DELETE' and count(1) = 0 from unnest(columns) c where c.is_pkey then
            -- Fan out 400 error per distinct selected_columns for this role
            for cols_record in
                select selected_columns
                from (select distinct selected_columns from unnest(subscriptions) s where s.claims_role = working_role) t
                order by coalesce(array_to_string(selected_columns, ','), '')
            loop
                working_selected_columns := cols_record.selected_columns;
                return next (
                    jsonb_build_object(
                        'schema', wal ->> 'schema',
                        'table', wal ->> 'table',
                        'type', action
                    ),
                    is_rls_enabled,
                    (select array_agg(s.subscription_id) from unnest(subscriptions) as s where s.claims_role = working_role and (s.selected_columns is not distinct from working_selected_columns)),
                    array['Error 400: Bad Request, no primary key']
                )::realtime.wal_rls;
            end loop;

        -- The claims role does not have SELECT permission to the primary key of entity
        elsif action <> 'DELETE' and sum(c.is_selectable::int) <> count(1) from unnest(columns) c where c.is_pkey then
            -- Fan out 401 error per distinct selected_columns for this role
            for cols_record in
                select selected_columns
                from (select distinct selected_columns from unnest(subscriptions) s where s.claims_role = working_role) t
                order by coalesce(array_to_string(selected_columns, ','), '')
            loop
                working_selected_columns := cols_record.selected_columns;
                return next (
                    jsonb_build_object(
                        'schema', wal ->> 'schema',
                        'table', wal ->> 'table',
                        'type', action
                    ),
                    is_rls_enabled,
                    (select array_agg(s.subscription_id) from unnest(subscriptions) as s where s.claims_role = working_role and (s.selected_columns is not distinct from working_selected_columns)),
                    array['Error 401: Unauthorized']
                )::realtime.wal_rls;
            end loop;

        else
            -- Create the prepared statement (once per role)
            if is_rls_enabled and action <> 'DELETE' then
                if (select 1 from pg_prepared_statements where name = 'walrus_rls_stmt' limit 1) > 0 then
                    deallocate walrus_rls_stmt;
                end if;
                execute realtime.build_prepared_statement_sql('walrus_rls_stmt', entity_, columns);
            end if;

            -- Collect all visible subscription IDs for this role (filter check + RLS check)
            visible_role_sub_ids = '{}';

            for subscription_id, claims in (
                    select
                        subs.subscription_id,
                        subs.claims
                    from
                        unnest(subscriptions) subs
                    where
                        subs.entity = entity_
                        and subs.claims_role = working_role
                        and (
                            realtime.is_visible_through_filters(columns, subs.filters)
                            or (
                              action = 'DELETE'
                              and realtime.is_visible_through_filters(old_columns, subs.filters)
                            )
                        )
            ) loop

                if not is_rls_enabled or action = 'DELETE' then
                    visible_role_sub_ids = visible_role_sub_ids || subscription_id;
                else
                    -- Check if RLS allows the role to see the record
                    perform
                        -- Trim leading and trailing quotes from working_role because set_config
                        -- doesn't recognize the role as valid if they are included
                        set_config('role', trim(both '"' from working_role::text), true),
                        set_config('request.jwt.claims', claims::text, true);

                    execute 'execute walrus_rls_stmt' into subscription_has_access;

                    -- Reset the role on every FOR..LOOP batch execution.
                    -- The first batch of 10 rows is pre-fetched using the current connection role (PG internal behaviour)
                    -- then we have to reset it again otherwise it would use the role defined in the `set_config` above
                    -- to fetch the remaining rows when rows>10, which could be a user-defined role that lacks execution grants.
                    -- The flow is:
                    --   1. run batch with conn role
                    --   2. set_config working_role
                    --   3. execute walrus
                    --   4. reset role (revert)
                    --   5. repeat
                    perform set_config('role', null, true);

                    if subscription_has_access then
                        visible_role_sub_ids = visible_role_sub_ids || subscription_id;
                    end if;
                end if;
            end loop;

            perform set_config('role', null, true);

            -- Inner loop: per distinct selected_columns for this role
            for cols_record in
                select selected_columns
                from (select distinct selected_columns from unnest(subscriptions) s where s.claims_role = working_role) t
                order by coalesce(array_to_string(selected_columns, ','), '')
            loop
                working_selected_columns := cols_record.selected_columns;

                output = jsonb_build_object(
                    'schema', wal ->> 'schema',
                    'table', wal ->> 'table',
                    'type', action,
                    'commit_timestamp', to_char(
                        ((wal ->> 'timestamp')::timestamptz at time zone 'utc'),
                        'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'
                    ),
                    'columns', (
                        select
                            jsonb_agg(
                                jsonb_build_object(
                                    'name', pa.attname,
                                    'type', pt.typname
                                )
                                order by pa.attnum asc
                            )
                        from
                            pg_attribute pa
                            join pg_type pt
                                on pa.atttypid = pt.oid
                            left join (
                                select unnest(conkey) as pkey_attnum
                                from pg_constraint
                                where conrelid = entity_ and contype = 'p'
                            ) pk on pk.pkey_attnum = pa.attnum
                        where
                            attrelid = entity_
                            and attnum > 0
                            and pg_catalog.has_column_privilege(working_role, entity_, pa.attname, 'SELECT')
                            and (working_selected_columns is null or pa.attname = any(working_selected_columns) or pk.pkey_attnum is not null)
                    )
                )
                -- Add "record" key for insert and update
                || case
                    when action in ('INSERT', 'UPDATE') then
                        jsonb_build_object(
                            'record',
                            (
                                select
                                    jsonb_object_agg(
                                        -- if unchanged toast, get column name and value from old record
                                        coalesce((c).name, (oc).name),
                                        case
                                            when (c).name is null then (oc).value
                                            else (c).value
                                        end
                                    )
                                from
                                    unnest(columns) c
                                    full outer join unnest(old_columns) oc
                                        on (c).name = (oc).name
                                where
                                    coalesce((c).is_selectable, (oc).is_selectable)
                                    and (working_selected_columns is null or coalesce((c).name, (oc).name) = any(working_selected_columns) or coalesce((c).is_pkey, (oc).is_pkey))
                                    and ( not error_record_exceeds_max_size or (octet_length((c).value::text) <= 64))
                            )
                        )
                    else '{}'::jsonb
                end
                -- Add "old_record" key for update and delete
                || case
                    when action = 'UPDATE' then
                        jsonb_build_object(
                                'old_record',
                                (
                                    select jsonb_object_agg((c).name, (c).value)
                                    from unnest(old_columns) c
                                    where
                                        (c).is_selectable
                                        and (working_selected_columns is null or (c).name = any(working_selected_columns) or (c).is_pkey)
                                        and ( not error_record_exceeds_max_size or (octet_length((c).value::text) <= 64))
                                )
                            )
                    when action = 'DELETE' then
                        jsonb_build_object(
                            'old_record',
                            (
                                select jsonb_object_agg((c).name, (c).value)
                                from unnest(old_columns) c
                                where
                                    (c).is_selectable
                                    and (working_selected_columns is null or (c).name = any(working_selected_columns) or (c).is_pkey)
                                    and ( not error_record_exceeds_max_size or (octet_length((c).value::text) <= 64))
                                    and ( not is_rls_enabled or (c).is_pkey ) -- if RLS enabled, we can't secure deletes so filter to pkey
                            )
                        )
                    else '{}'::jsonb
                end;

                -- Filter visible_role_sub_ids to those matching the current selected_columns group
                visible_to_subscription_ids = coalesce(
                    (
                        select array_agg(s.subscription_id)
                        from unnest(subscriptions) s
                        where s.claims_role = working_role
                          and (s.selected_columns is not distinct from working_selected_columns)
                          and s.subscription_id = any(visible_role_sub_ids)
                    ),
                    '{}'::uuid[]
                );

                return next (
                    output,
                    is_rls_enabled,
                    visible_to_subscription_ids,
                    case
                        when error_record_exceeds_max_size then array['Error 413: Payload Too Large']
                        else '{}'
                    end
                )::realtime.wal_rls;
            end loop;

        end if;
    end loop;

    perform set_config('role', null, true);
end;
$$;


ALTER FUNCTION realtime.apply_rls(wal jsonb, max_record_bytes integer) OWNER TO supabase_realtime_admin;

--
-- Name: authorize(text, text, text, text, text, text[], text[]); Type: FUNCTION; Schema: realtime; Owner: supabase_realtime_admin
--

CREATE FUNCTION realtime.authorize(role_name text, topic_name text, claims text, sub text, headers text, read_extensions text[], write_extensions text[], OUT read_allowed boolean[], OUT write_allowed boolean[]) RETURNS record
    LANGUAGE plpgsql
    AS $$
declare
  probe_ids uuid[];
  ext text;
  allowed boolean;
begin
  -- The probe inserts are rolled back, but they still give the transaction an xid, so it ends
  -- in a commit. Nothing durable was written, so skip waiting on the WAL flush and sync standbys.
  -- Set outside the block below, whose rollback would undo it.
  perform set_config('synchronous_commit', 'off', true);

  -- The RAISE at the end of this block rolls back everything in it.
  begin
    probe_ids := array(select gen_random_uuid() from unnest(read_extensions));

    insert into realtime.messages (id, topic, extension, inserted_at, updated_at)
    select p.id, topic_name, p.extension, now() at time zone 'utc', now() at time zone 'utc'
    from unnest(probe_ids, read_extensions) as p(id, extension);

    perform set_config('role', role_name, true),
            set_config('realtime.topic', topic_name, true),
            set_config('request.jwt.claims', claims, true),
            set_config('request.jwt.claim.sub', sub, true),
            set_config('request.jwt.claim.role', role_name, true),
            set_config('request.headers', headers, true);

    read_allowed := array(
      select exists(select 1 from realtime.messages m where m.id = p.id)
      from unnest(probe_ids) with ordinality as p(id, n)
      order by p.n);

    write_allowed := '{}';

    foreach ext in array write_extensions loop
      begin
        insert into realtime.messages (topic, extension, inserted_at, updated_at)
        values (topic_name, ext, now() at time zone 'utc', now() at time zone 'utc');

        allowed := true;
      exception when insufficient_privilege then
        allowed := false;
      end;

      write_allowed := write_allowed || allowed;
    end loop;

    raise sqlstate 'RTA01';
  exception when sqlstate 'RTA01' then
    null;
  end;
end;
$$;


ALTER FUNCTION realtime.authorize(role_name text, topic_name text, claims text, sub text, headers text, read_extensions text[], write_extensions text[], OUT read_allowed boolean[], OUT write_allowed boolean[]) OWNER TO supabase_realtime_admin;

--
-- Name: broadcast_changes(text, text, text, text, text, record, record, text); Type: FUNCTION; Schema: realtime; Owner: supabase_realtime_admin
--

CREATE FUNCTION realtime.broadcast_changes(topic_name text, event_name text, operation text, table_name text, table_schema text, new record, old record, level text DEFAULT 'ROW'::text) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    -- Declare a variable to hold the JSONB representation of the row
    row_data jsonb := '{}'::jsonb;
BEGIN
    IF level = 'STATEMENT' THEN
        RAISE EXCEPTION 'function can only be triggered for each row, not for each statement';
    END IF;
    -- Check the operation type and handle accordingly
    IF operation = 'INSERT' OR operation = 'UPDATE' OR operation = 'DELETE' THEN
        row_data := jsonb_build_object('old_record', OLD, 'record', NEW, 'operation', operation, 'table', table_name, 'schema', table_schema);
        PERFORM realtime.send (row_data, event_name, topic_name);
    ELSE
        RAISE EXCEPTION 'Unexpected operation type: %', operation;
    END IF;
EXCEPTION
    WHEN OTHERS THEN
        RAISE EXCEPTION 'Failed to process the row: %', SQLERRM;
END;

$$;


ALTER FUNCTION realtime.broadcast_changes(topic_name text, event_name text, operation text, table_name text, table_schema text, new record, old record, level text) OWNER TO supabase_realtime_admin;

--
-- Name: build_prepared_statement_sql(text, regclass, realtime.wal_column[]); Type: FUNCTION; Schema: realtime; Owner: supabase_realtime_admin
--

CREATE FUNCTION realtime.build_prepared_statement_sql(prepared_statement_name text, entity regclass, columns realtime.wal_column[]) RETURNS text
    LANGUAGE sql
    AS $$
      /*
      Builds a sql string that, if executed, creates a prepared statement to
      tests retrive a row from *entity* by its primary key columns.
      Example
          select realtime.build_prepared_statement_sql('public.notes', '{"id"}'::text[], '{"bigint"}'::text[])
      */
          select
      'prepare ' || prepared_statement_name || ' as
          select
              exists(
                  select
                      1
                  from
                      ' || entity || '
                  where
                      ' || string_agg(quote_ident(pkc.name) || '=' || quote_nullable(pkc.value #>> '{}') , ' and ') || '
              )'
          from
              unnest(columns) pkc
          where
              pkc.is_pkey
          group by
              entity
      $$;


ALTER FUNCTION realtime.build_prepared_statement_sql(prepared_statement_name text, entity regclass, columns realtime.wal_column[]) OWNER TO supabase_realtime_admin;

--
-- Name: cast(text, regtype); Type: FUNCTION; Schema: realtime; Owner: supabase_realtime_admin
--

CREATE FUNCTION realtime."cast"(val text, type_ regtype) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    AS $$
declare
  res jsonb;
begin
  if type_::text = 'bytea' then
    return to_jsonb(val);
  end if;
  execute format('select to_jsonb(%L::'|| type_::text || ')', val) into res;
  return res;
end
$$;


ALTER FUNCTION realtime."cast"(val text, type_ regtype) OWNER TO supabase_realtime_admin;

--
-- Name: check_equality_op(realtime.equality_op, regtype, text, text); Type: FUNCTION; Schema: realtime; Owner: supabase_realtime_admin
--

CREATE FUNCTION realtime.check_equality_op(op realtime.equality_op, type_ regtype, val_1 text, val_2 text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    AS $$
/*
Casts *val_1* and *val_2* as type *type_* and check the *op* condition for truthiness
*/
declare
    op_symbol text = (
        case
            when op = 'eq' then '='
            when op = 'neq' then '!='
            when op = 'lt' then '<'
            when op = 'lte' then '<='
            when op = 'gt' then '>'
            when op = 'gte' then '>='
            when op = 'in' then '= any'
            else 'UNKNOWN OP'
        end
    );
    res boolean;
begin
    execute format(
        'select %L::'|| type_::text || ' ' || op_symbol
        || ' ( %L::'
        || (
            case
                when op = 'in' then type_::text || '[]'
                else type_::text end
        )
        || ')', val_1, val_2) into res;
    return res;
end;
$$;


ALTER FUNCTION realtime.check_equality_op(op realtime.equality_op, type_ regtype, val_1 text, val_2 text) OWNER TO supabase_realtime_admin;

--
-- Name: check_equality_op(realtime.equality_op, regtype, text, text, boolean); Type: FUNCTION; Schema: realtime; Owner: supabase_realtime_admin
--

CREATE FUNCTION realtime.check_equality_op(op realtime.equality_op, type_ regtype, val_1 text, val_2 text, negate boolean) RETURNS boolean
    LANGUAGE plpgsql STABLE
    AS $$
declare
    op_symbol text;
    res boolean;
begin
    -- IS DISTINCT FROM / IS NOT DISTINCT FROM: infix, both sides typed literals
    if op = 'isdistinct' then
        execute format(
            'select %L::%s %s %L::%s',
            val_1,
            type_::text,
            case when negate then 'IS NOT DISTINCT FROM' else 'IS DISTINCT FROM' end,
            val_2,
            type_::text
        ) into res;
        return res;
    end if;

    -- IS requires a keyword RHS (NULL, TRUE, FALSE, UNKNOWN), not a typed literal
    if op = 'is' then
        if val_2 not in ('null', 'true', 'false', 'unknown') then
            raise exception 'invalid value for is filter: must be null, true, false, or unknown';
        end if;
        execute format(
            'select %L::%s %s %s',
            val_1,
            type_::text,
            case when negate then 'IS NOT' else 'IS' end,
            upper(val_2)
        ) into res;
        return res;
    end if;

    op_symbol = case
        when op = 'eq'    then '='
        when op = 'neq'   then '!='
        when op = 'lt'    then '<'
        when op = 'lte'   then '<='
        when op = 'gt'    then '>'
        when op = 'gte'   then '>='
        when op = 'in'    then '= any'
        when op = 'like'   then 'LIKE'
        when op = 'ilike'  then 'ILIKE'
        when op = 'match'  then '~'
        when op = 'imatch' then '~*'
        else null
    end;

    if op_symbol is null then
        raise exception 'unsupported equality operator: %', op::text;
    end if;

    execute format(
        'select %L::%s %s (%L::%s)',
        val_1,
        type_::text,
        op_symbol,
        val_2,
        case when op = 'in' then type_::text || '[]' else type_::text end
    ) into res;

    return case when negate then not res else res end;
end;
$$;


ALTER FUNCTION realtime.check_equality_op(op realtime.equality_op, type_ regtype, val_1 text, val_2 text, negate boolean) OWNER TO supabase_realtime_admin;

--
-- Name: is_visible_through_filters(realtime.wal_column[], realtime.user_defined_filter[]); Type: FUNCTION; Schema: realtime; Owner: supabase_realtime_admin
--

CREATE FUNCTION realtime.is_visible_through_filters(columns realtime.wal_column[], filters realtime.user_defined_filter[]) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
    select
        filters is null
        or array_length(filters, 1) is null
        or coalesce(
            count(col.name) = count(1)
            and sum(
                realtime.check_equality_op(
                    op:=f.op,
                    type_:=coalesce(col.type_oid::regtype, col.type_name::regtype),
                    val_1:=col.value #>> '{}',
                    val_2:=f.value,
                    negate:=coalesce(f.negate, false)
                )::int
            ) filter (where col.name is not null) = count(col.name),
            false
        )
    from
        unnest(filters) f
        left join unnest(columns) col
            on f.column_name = col.name;
$$;


ALTER FUNCTION realtime.is_visible_through_filters(columns realtime.wal_column[], filters realtime.user_defined_filter[]) OWNER TO supabase_realtime_admin;

--
-- Name: list_changes(name, name, integer, integer); Type: FUNCTION; Schema: realtime; Owner: supabase_realtime_admin
--

CREATE FUNCTION realtime.list_changes(publication name, slot_name name, max_changes integer, max_record_bytes integer) RETURNS TABLE(wal jsonb, is_rls_enabled boolean, subscription_ids uuid[], errors text[], slot_changes_count bigint)
    LANGUAGE sql
    SET log_min_messages TO 'fatal'
    AS $$
  WITH pub AS (
    SELECT
      concat_ws(
        ',',
        CASE WHEN bool_or(pubinsert) THEN 'insert' ELSE NULL END,
        CASE WHEN bool_or(pubupdate) THEN 'update' ELSE NULL END,
        CASE WHEN bool_or(pubdelete) THEN 'delete' ELSE NULL END
      ) AS w2j_actions,
      coalesce(
        string_agg(
          realtime.quote_wal2json(format('%I.%I', schemaname, tablename)::regclass),
          ','
        ) filter (WHERE ppt.tablename IS NOT NULL),
        ''
      ) AS w2j_add_tables
    FROM pg_publication pp
    LEFT JOIN pg_publication_tables ppt ON pp.pubname = ppt.pubname
    WHERE pp.pubname = publication
    GROUP BY pp.pubname
    LIMIT 1
  ),
  -- MATERIALIZED ensures pg_logical_slot_get_changes is called exactly once
  w2j AS MATERIALIZED (
    SELECT x.*, pub.w2j_add_tables
    FROM pub,
         pg_logical_slot_get_changes(
           slot_name, null, max_changes,
           'include-pk', 'true',
           'include-transaction', 'false',
           'include-timestamp', 'true',
           'include-type-oids', 'true',
           'format-version', '2',
           'actions', pub.w2j_actions,
           'add-tables', pub.w2j_add_tables
         ) x
  ),
  slot_count AS (
    SELECT count(*)::bigint AS cnt
    FROM w2j
    WHERE w2j.w2j_add_tables <> ''
  ),
  rls_filtered AS (
    SELECT xyz.wal, xyz.is_rls_enabled, xyz.subscription_ids, xyz.errors
    FROM w2j,
         realtime.apply_rls(
           wal := w2j.data::jsonb,
           max_record_bytes := max_record_bytes
         ) xyz(wal, is_rls_enabled, subscription_ids, errors)
    WHERE w2j.w2j_add_tables <> ''
      AND xyz.subscription_ids[1] IS NOT NULL
  )
  SELECT rf.wal, rf.is_rls_enabled, rf.subscription_ids, rf.errors, sc.cnt
  FROM rls_filtered rf, slot_count sc

  UNION ALL

  SELECT null, null, null, null, sc.cnt
  FROM slot_count sc
  WHERE NOT EXISTS (SELECT 1 FROM rls_filtered)
$$;


ALTER FUNCTION realtime.list_changes(publication name, slot_name name, max_changes integer, max_record_bytes integer) OWNER TO supabase_realtime_admin;

--
-- Name: list_changes_sync(name, name, integer, integer); Type: FUNCTION; Schema: realtime; Owner: supabase_realtime_admin
--

CREATE FUNCTION realtime.list_changes_sync(publication name, slot_name name, max_changes integer, max_record_bytes integer) RETURNS TABLE(wal jsonb, is_rls_enabled boolean, subscription_ids uuid[], errors text[], slot_changes_count bigint)
    LANGUAGE sql
    SET log_min_messages TO 'fatal'
    AS $$
  WITH pub AS (
    SELECT
      concat_ws(
        ',',
        CASE WHEN bool_or(pubinsert) THEN 'insert' ELSE NULL END,
        CASE WHEN bool_or(pubupdate) THEN 'update' ELSE NULL END,
        CASE WHEN bool_or(pubdelete) THEN 'delete' ELSE NULL END
      ) AS w2j_actions,
      coalesce(
        string_agg(
          realtime.quote_wal2json(format('%I.%I', schemaname, tablename)::regclass),
          ','
        ) filter (WHERE ppt.tablename IS NOT NULL),
        ''
      ) AS w2j_add_tables
    FROM pg_publication pp
    LEFT JOIN pg_publication_tables ppt ON pp.pubname = ppt.pubname
    WHERE pp.pubname = publication
    GROUP BY pp.pubname
    LIMIT 1
  ),
  -- MATERIALIZED ensures the slot is read exactly once.
  consumed AS MATERIALIZED (
    SELECT x.*, pub.w2j_add_tables
    FROM pub,
         realtime.settled_changes(
           slot_name, max_changes,
           'include-pk', 'true',
           'include-transaction', 'false',
           'include-timestamp', 'true',
           'include-type-oids', 'true',
           'format-version', '2',
           'actions', pub.w2j_actions,
           'add-tables', pub.w2j_add_tables
         ) x
  ),
  slot_count AS (
    SELECT count(*)::bigint AS cnt
    FROM consumed
    WHERE consumed.w2j_add_tables <> ''
  ),
  rls_filtered AS (
    SELECT xyz.wal, xyz.is_rls_enabled, xyz.subscription_ids, xyz.errors
    FROM consumed,
         realtime.apply_rls(
           wal := consumed.data::jsonb,
           max_record_bytes := max_record_bytes
         ) xyz(wal, is_rls_enabled, subscription_ids, errors)
    WHERE consumed.w2j_add_tables <> ''
      AND xyz.subscription_ids[1] IS NOT NULL
  )
  SELECT rf.wal, rf.is_rls_enabled, rf.subscription_ids, rf.errors, sc.cnt
  FROM rls_filtered rf, slot_count sc

  UNION ALL

  SELECT null, null, null, null, sc.cnt
  FROM slot_count sc
  WHERE NOT EXISTS (SELECT 1 FROM rls_filtered)
$$;


ALTER FUNCTION realtime.list_changes_sync(publication name, slot_name name, max_changes integer, max_record_bytes integer) OWNER TO supabase_realtime_admin;

--
-- Name: quote_wal2json(regclass); Type: FUNCTION; Schema: realtime; Owner: supabase_realtime_admin
--

CREATE FUNCTION realtime.quote_wal2json(entity regclass) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    AS $$
  SELECT
    realtime.wal2json_escape_identifier(nsp.nspname::text)
    || '.'
    || realtime.wal2json_escape_identifier(pc.relname::text)
  FROM pg_class pc
  JOIN pg_namespace nsp ON pc.relnamespace = nsp.oid
  WHERE pc.oid = entity
$$;


ALTER FUNCTION realtime.quote_wal2json(entity regclass) OWNER TO supabase_realtime_admin;

--
-- Name: send(jsonb, text, text, boolean); Type: FUNCTION; Schema: realtime; Owner: supabase_realtime_admin
--

CREATE FUNCTION realtime.send(payload jsonb, event text, topic text, private boolean DEFAULT true) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  generated_id uuid;
  final_payload jsonb;
BEGIN
  BEGIN
    generated_id := gen_random_uuid();

    -- Check if payload has an 'id' key, if not, add the generated UUID
    IF payload ? 'id' THEN
      final_payload := payload;
    ELSE
      final_payload := jsonb_set(payload, '{id}', to_jsonb(generated_id));
    END IF;

    -- Set the topic configuration
    EXECUTE format('SET LOCAL realtime.topic TO %L', topic);

    INSERT INTO realtime.messages (id, payload, event, topic, private, extension)
    VALUES (generated_id, final_payload, event, topic, private, 'broadcast');
  EXCEPTION
    WHEN OTHERS THEN
      RAISE WARNING 'WarnSendingBroadcastMessage: %', SQLERRM;
  END;
END;
$$;


ALTER FUNCTION realtime.send(payload jsonb, event text, topic text, private boolean) OWNER TO supabase_realtime_admin;

