--
-- Name: customer_overview; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.customer_overview AS
 SELECT c.id,
    c.name,
    c.phone,
    c.email,
    c.location_id,
    l.name AS location_name,
    c.address,
    c.status,
    c.notes,
    ( SELECT count(*) AS count
           FROM public.projects p
          WHERE (p.customer_id = c.id)) AS project_count
   FROM (public.customers c
     LEFT JOIN public.locations l ON ((l.id = c.location_id)))
  ORDER BY c.created_at DESC;


