    type text NOT NULL,
    category text NOT NULL,
    description text NOT NULL,
    amount numeric(14,2) NOT NULL,
    method text NOT NULL,
    reference text,
    location text,
    status text DEFAULT 'draft'::text NOT NULL,
    recon_status text DEFAULT 'na'::text,
    notes text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by text,
    updated_at timestamp with time zone,
    updated_by text,
    approved_at timestamp with time zone,
    approved_by text,
    rejected_at timestamp with time zone,
    rejected_by text,
    location_id bigint,
    staff_id bigint,
    payroll_run_id bigint,
    deleted_at timestamp with time zone,
    deleted_by text,
    delete_reason text,
    actual_date date,
    actual_time time without time zone,
    fee numeric(14,2) DEFAULT 0 NOT NULL,
    net_amount numeric(14,2),
    source text DEFAULT 'manual'::text,
    idempotency_key text,
    reversal_of text,
    reversed_at timestamp with time zone,
    reversed_by text,
    reversal_reason text,
    CONSTRAINT transactions_amount_check CHECK ((amount > (0)::numeric)),
    CONSTRAINT transactions_recon_status_check CHECK ((recon_status = ANY (ARRAY['na'::text, 'unmatched'::text, 'matched'::text, 'verified'::text, 'reconciled'::text]))),
    CONSTRAINT transactions_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'pending'::text, 'approved'::text, 'posted'::text, 'rejected'::text]))),
    CONSTRAINT transactions_type_check CHECK ((type = ANY (ARRAY['income'::text, 'expense'::text, 'capital'::text])))
);


