CREATE VIEW public.starlink_virtual_capital_total AS
 SELECT COALESCE(sum(amount), (0)::numeric) AS total
   FROM public.transactions
  WHERE ((type = 'expense'::text) AND (category = 'STARLINK Virtual Capital'::text) AND (status = 'posted'::text) AND (deleted_at IS NULL) AND (reversed_at IS NULL));


