);


ALTER TABLE public.tasks OWNER TO postgres;

--
-- Name: task_dashboard_summary; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.task_dashboard_summary AS
 SELECT count(*) FILTER (WHERE (status = 'draft'::text)) AS draft_count,
    count(*) FILTER (WHERE (status = 'assigned'::text)) AS assigned_count,
    count(*) FILTER (WHERE (status = 'accepted'::text)) AS accepted_count,
    count(*) FILTER (WHERE (status = 'in_progress'::text)) AS in_progress_count,
    count(*) FILTER (WHERE (status = 'awaiting_review'::text)) AS awaiting_review_count,
    count(*) FILTER (WHERE (status = 'approved'::text)) AS approved_count,
    count(*) FILTER (WHERE (status = 'rejected'::text)) AS rejected_count,
    count(*) FILTER (WHERE (status = 'completed'::text)) AS completed_count,
    count(*) FILTER (WHERE (status = 'cancelled'::text)) AS cancelled_count,
    count(*) FILTER (WHERE (status = 'on_hold'::text)) AS on_hold_count,
    count(*) AS total_count,
    count(*) FILTER (WHERE ((deadline IS NOT NULL) AND (deadline < CURRENT_DATE) AND (status <> ALL (ARRAY['completed'::text, 'cancelled'::text, 'rejected'::text])))) AS overdue_count,
    count(*) FILTER (WHERE (priority = 'high'::text)) AS high_priority_count,
    count(*) FILTER (WHERE (priority = 'urgent'::text)) AS urgent_priority_count,
    count(*) FILTER (WHERE ((deadline = CURRENT_DATE) AND (status <> ALL (ARRAY['completed'::text, 'cancelled'::text])))) AS due_today_count
   FROM public.tasks
  WHERE (deleted_at IS NULL);


ALTER VIEW public.task_dashboard_summary OWNER TO postgres;

